/// \input    IL_ui8_TabMessageStaticRcpData28[0]                                           = 1u;        // AIMING_MODE_ACTIVATION
/// \input    IL_ui8_TabMessageStaticRcpData29[0]                                           = 1u;        // PEDESTRIAN_ALLOWED
/// \input    IL_ui8_TabMessageStaticRcpData31[0]                                           = 1u;        // MOTORWAY_DETECTION
