/// \input  SysMonCheck_LedCtrl_pTargetLed_ASIL->asTgtVal[ulLedIdx].unDutyCycle        = 10;
/// \input  SysMonCheck_LedCtrl_pTargetLed[ulLedIdx].unCurrent                         = 1u;
/// \input  SysMonCheck_LedtCtrl_pLedChParam[ulLedIdx].unMinCurrent                    = 5u;
/// \input  SysMonCheck_LedCtrl_pTargetLed[ulLedIdx].unDutyCycle                       = 1u;
/// \input  SysMonCheck_LedtCtrl_pLedChParam[ulLedIdx].unMinPwmDuty                    = 5u;
/// \input  SysMonRx_ASIL_boEmergencyOperationLowBeam                                  = TRUE;
/// \input  SysMonRx_ASIL_boEmergencyOperationTurnIndicator                            = TRUE; // enter TI emergency
