  SysMonCheck_boInitialized                                   = TRUE;
  Rte_Read_CodM_SysMon_Para_Param1.psCodingParameters_Blocks  = &CodingDummy;
  Rte_Read_CodM_SysMon_Para_Param1.eCodingState               = eParaFct0_CodingDataInvalid;
  SysMonRx_ASIL_sSignalLowBeam.ucValue                        = 0u;
  SysMonRx_ASIL_sSignalTurnIndicator.ucValue                  = SYSMON_TURNINDICATOR_OFF;

  //Step 3) Call FUT
