  LPTMR0_GetTimeElapsed_RetVal = 30u;
  SysMonRx_Callbacks_sTimerCfg[SYSMONRX_CALLBACKS_CRCERR_TIMER].boStartStopTimer = TRUE;
  SysMonRx_Callbacks_sTimerCfg[SYSMONRX_CALLBACKS_CRCERR_TIMER].ulCommandStart = 120u;
  SysMonRx_Callbacks_EvaluateCrcAndAliveDtcs_RetVal = SIG_E2E_CRCERR;

  //Step 7) Call FUT Second function call
